module tb_TopModule;
    reg [3:0] in;
    wire out_and;
    wire out_or;
    wire out_xor;

    TopModule uut (
        .in(in),
        .out_and(out_and),
        .out_or(out_or),
        .out_xor(out_xor)
    );

    initial begin
        integer i;
        reg exp_and, exp_or, exp_xor;

        for (i = 0; i < 16; i = i + 1) begin
            in = i[3:0];
            #10;
            exp_and = &in[3:0];
            exp_or  = |in[3:0];
            exp_xor = ^in[3:0];

            if (out_and !== exp_and || out_or !== exp_or || out_xor !== exp_xor) begin
                $display("SELFFAIL: in=%b, got (and=%b, or=%b, xor=%b), expected (and=%b, or=%b, xor=%b)",
                         in, out_and, out_or, out_xor, exp_and, exp_or, exp_xor);
                $finish;
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
